typedef struct LetterOps {                       /* the letter interface */
    int  (*read)(void *self, char *buf, size_t n);
    void (*destroy)(void *self);
} LetterOps;

struct Envelope { const LetterOps *ops; void *letter; };   /* the envelope */
int envelope_read(struct Envelope *e, char *buf, size_t n) {
    return e->ops->read(e->letter, buf, n);       /* forwarding */
}
struct Envelope envelope_open(const LetterOps *ops, void *letter) {
    return (struct Envelope){ ops, letter };
}
